async function init(){
  const { data } = await db.auth.getSession();
  session = data.session;
  db.auth.onAuthStateChange((e,s)=>{ if(e==='PASSWORD_RECOVERY') window.__recovery=true; const had=!!session; session=s; if(had!==!!s || e==='PASSWORD_RECOVERY') render(); });
  render();
}

function showLogin(){
  $('#sidebar').style.display='none';
  app.innerHTML = `<div class="card" id="login">
    <div class="center" style="margin-bottom:16px">
      <div class="pf" style="letter-spacing:9px;font-size:21px;color:var(--forest);font-weight:500">MALDIVIA</div>
      <div style="font-size:8.5px;letter-spacing:3.5px;color:var(--gold);text-transform:uppercase;margin-top:4px;font-weight:700">Travel Design · Panda</div></div>
    <form id="loginform">
      <label for="em">E-mail</label><input id="em" name="email" type="email" autocomplete="username" required>
      <label for="pw">Kodeord</label><input id="pw" name="password" type="password" autocomplete="current-password" required minlength="6">
      <div style="margin-top:15px" class="row">
        <button class="btn" type="submit">Log ind</button>
      </div>
      <div style="margin-top:10px"><button type="button" id="forgotbtn" style="padding:0;background:none;border:none;color:var(--gold);font-size:11.5px;cursor:pointer;text-decoration:underline;font-family:inherit">Glemt kodeord?</button></div>
    </form>
    <div class="err" id="autherr"></div>
    <p class="muted">Kun teamets e-mailadresser får adgang til data.</p></div>`;
  const msg=(t,ok)=>{const e=$('#autherr');e.className=ok?'err ok':'err';e.textContent=t;};
  const creds=()=>{const fd=new FormData(document.getElementById('loginform'));return{email:String(fd.get('email')||'').trim().toLowerCase(),password:String(fd.get('password')||'')};};
  document.getElementById('loginform').addEventListener('submit', async ev=>{
    ev.preventDefault(); const c=creds();
    if(!c.email||!c.password) return msg('Udfyld både e-mail og kodeord.');
    msg('Logger ind…',true);
    const {error}=await db.auth.signInWithPassword(c);
    if(error) msg(/invalid/i.test(error.message)?'Forkert e-mail eller kodeord.':/confirm/i.test(error.message)?'E-mail ikke bekræftet — sig til Claude.':error.message);
  });
  // Selv-registrering er fjernet (v0.7): nye brugere oprettes af en admin på Brugere-siden,
  // som også opretter login'et og udleverer et engangskodeord.
  document.getElementById('forgotbtn').addEventListener('click', async ()=>{
    const c=creds();
    if(!c.email) return msg('Skriv din e-mail i feltet ovenfor, tryk så «Glemt kodeord?».');
    msg('Sender link…',true);
    const {error}=await db.auth.resetPasswordForEmail(c.email, {redirectTo: location.origin+location.pathname});
    msg(error?error.message:'Vi har sendt et link til '+c.email+'. Åbn mailen og vælg et nyt kodeord (tjek evt. spam-mappen).',!error);
  });
}

function changePassword(){
  if(document.getElementById('cpoverlay')) return;
  const ov=document.createElement('div');
  ov.id='cpoverlay';
  ov.style.cssText='position:fixed;inset:0;background:rgba(34,48,31,.35);display:flex;align-items:center;justify-content:center;z-index:9999';
  ov.innerHTML=`<div class="card" style="width:360px;max-width:92vw;margin:0">
    <h3 style="margin-top:0">Skift kodeord</h3>
    <label for="cpw1">Nyt kodeord</label><input id="cpw1" type="password" autocomplete="new-password" minlength="6">
    <label for="cpw2">Gentag nyt kodeord</label><input id="cpw2" type="password" autocomplete="new-password" minlength="6">
    <div class="err" id="cperr" style="margin-top:8px"></div>
    <div class="row" style="margin-top:14px">
      <button class="btn" id="cpsave" type="button">Gem</button>
      <button class="btn ghost" id="cpcancel" type="button">Annullér</button>
    </div>
    <p class="muted" style="margin-bottom:0">Mindst 6 tegn.</p></div>`;
  document.body.appendChild(ov);
  const err=(t,ok)=>{const e=ov.querySelector('#cperr');e.className=ok?'err ok':'err';e.textContent=t;};
  const close=()=>ov.remove();
  ov.addEventListener('click', e=>{ if(e.target===ov) close(); });
  ov.querySelector('#cpcancel').onclick=close;
  ov.querySelector('#cpw1').focus();
  ov.querySelector('#cpsave').onclick=async()=>{
    const p1=ov.querySelector('#cpw1').value, p2=ov.querySelector('#cpw2').value;
    if(p1.length<6) return err('Kodeordet skal være mindst 6 tegn.');
    if(p1!==p2) return err('De to kodeord er ikke ens.');
    err('Gemmer…',true);
    const {error}=await db.auth.updateUser({password:p1});
    if(error) return err(error.message);
    err('Kodeord ændret ✓ — brug det næste gang du logger ind.',true);
    setTimeout(close,1600);
  };
}

async function showApp(){
  $('#sidebar').style.display='';
  const email = session.user.email;
  window.MYEMAIL = email;
  const [tmr, rr] = await Promise.all([
    db.from('team_members').select('email, name, initials, role, permission_overrides, active').eq('email', email).maybeSingle(),
    db.from('roles').select('role_key, label, description, permissions, sort_order').order('sort_order')
  ]);
  const tm = tmr.data;
  window.ROLES = rr.data || [];
  if(!tm || tm.active===false){
    window.ME=null; window.PERMS={};
    document.querySelectorAll('#nav button').forEach(b=>b.style.display='none');
    $('#who').innerHTML = email + '<br><a href="#" onclick="db.auth.signOut();return false">'+t('g.logout')+'</a>' + langPicker();
    app.innerHTML = '<div class="card"><h3>Ingen adgang</h3><p class="muted">Din bruger ('+email+') er ikke aktiv i systemet. Kontakt Wendie eller Rasmus.</p></div>';
    return;
  }
  window.ME = tm.initials; window.MYNAME = tm.name.split(' ')[0];
  const roleDef = window.ROLES.find(r=>r.role_key===tm.role);
  // Effektive rettigheder = rolle-standarder + individuelle undtagelser (spejler public.my_permissions() i databasen)
  window.PERMS = Object.assign({economy:false,finance:false,reports:true,leads:true,manage_users:false}, (roleDef&&roleDef.permissions)||{}, tm.permission_overrides||{});
  applyNavPerms();
  checkTestdata();
  $('#who').innerHTML = tm.name + (roleDef?' <span class="muted">· '+roleDef.label+'</span>':'') + '<br><a href="#" onclick="changePassword();return false">'+t('g.changepw')+'</a> · <a href="#" onclick="db.auth.signOut();return false">'+t('g.logout')+'</a>' + langPicker();
  applyI18n();
  applyRoute();
  setupRealtime();
  if(window.__recovery){ window.__recovery=false; setTimeout(changePassword, 500); }
}

function applyNavPerms(){
  const vis = {hv:hasPerm('leads'), finance:hasPerm('finance'), reports:hasPerm('reports'),
               settings:hasPerm('manage_users')};
  document.querySelectorAll('#nav button').forEach(b=>{ if(b.dataset.v in vis) b.style.display = vis[b.dataset.v]?'':'none'; });
}
